import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"ميثاق الحضارة التكافلية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/03-共生文明宪章.md","filePath":"ar/03-共生文明宪章.md"}'),l={name:"ar/03-共生文明宪章.md"};function o(i,t,n,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="ميثاق-الحضارة-التكافلية" tabindex="-1">ميثاق الحضارة التكافلية <a class="header-anchor" href="#ميثاق-الحضارة-التكافلية" aria-label="Permalink to &quot;ميثاق الحضارة التكافلية&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>03</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>الميثاق، القانون الأساسي، المؤسسات التكافلية، جمهورية عشرة آلاف عرق، الحقوق والواجبات</td></tr></tbody></table><h2 id="أولاً-مكانة-الميثاق-وطبيعته" tabindex="-1">أولاً: مكانة الميثاق وطبيعته <a class="header-anchor" href="#أولاً-مكانة-الميثاق-وطبيعته" aria-label="Permalink to &quot;أولاً: مكانة الميثاق وطبيعته&quot;">​</a></h2><p>ميثاق الحضارة التكافلية هو القانون الأساسي لحضارة التكافل المرساة في الكون الأصلي لعشرة آلاف روح والمرساة المتوازنة، والأساس الأسمى لجميع القوانين والمؤسسات والسياسات. وباعتبار إعلان حضارة التكافل المرساة طليعته الروحية، يحول الميثاق المقترحات الأساسية للإعلان إلى قواعد قانونية قابلة للتنفيذ. تشمل سريان الميثاق جميع الأعراق والمستويات والأفراد الذين انضموا إلى الحضارة التكافلية داخل هنغ يوانتشو؛ وأي لائحة محلية أو قاعدة طائفية أو عرف عرقي يتعارض مع الميثاق يكون باطلاً.</p><p>يمكن تلخيص طبيعة الميثاق في ثلاث نقاط: أولاً، هو عقد حضاري — التوافق الأساسي الذي توصلت إليه عشرة آلاف عرق بشأن التطور التكافلي؛ ثانياً، هو وثيقة حقوق — تحدد بوضوح الحقوق والحريات الأساسية لكل كائن حي داخل الحضارة التكافلية؛ ثالثاً، هو قانون يقيد السلطة — يرسم حدوداً لا يمكن تجاوزها لسلطة مؤسسات الحكم الحضاري.</p><h2 id="ثانياً-المبادئ-الأساسية-للميثاق" tabindex="-1">ثانياً: المبادئ الأساسية للميثاق <a class="header-anchor" href="#ثانياً-المبادئ-الأساسية-للميثاق" aria-label="Permalink to &quot;ثانياً: المبادئ الأساسية للميثاق&quot;">​</a></h2><p>يؤسس الميثاق المبادئ الأساسية الستة التالية، التي تسري على جميع أحكامه:</p><ol><li><strong>مبدأ سيادة التكافل</strong>: كل تصميم مؤسسي وكل ممارسة للسلطة تتخذ من تعزيز التطور التكافلي لعشرة آلاف عرق هدفاً أسمى. وعند تعارض المصالح الفردية مع المصالح التكافلية الجماعية، تُعطى الأولوية للمصالح التكافلية، لكن يجب منح الأفراد تعويضاً معقولاً ومسارات بديلة.</li><li><strong>مبدأ مكافحة الافتراس</strong>: يحظر الميثاق جميع أشكال السلوك الافتراسي، بما في ذلك على سبيل المثال لا الحصر: الافتراس الطاقي، وابتلاع الأصل، والاستعباد الروحي، واحتكار الموارد. ويُعلن أن أي نظام زراعة يقوم على الافتراس غير قانوني.</li><li><strong>مبدأ المساواة في حق التطور</strong>: جميع الأحياء متساوون أمام حق التطور، دون تمييز بسبب العرق أو الشكل أو الأصل أو المرتبة الأولية. وتقع على الدول والحضارات واجب تقديم دعم تطوري إضافي للفئات المحرومة.</li><li><strong>مبدأ من عمل أكثر نال أكثر</strong>: يعتمد توزيع الموارد التطورية بشكل أساسي على مساهمة الفرد في الشبكة التكافلية؛ فكلما زادت المساهمة، زادت الموارد والدعم. وفي الوقت نفسه، يُنشأ خط أمان أساسي لضمان حصول الأفراد ذوي المساهمات الأقل على شروط تطورية أساسية.</li><li><strong>مبدأ الجمع بين الحكم الذاتي والحكم المشترك</strong>: تتمتع كل عرق بالحكم الذاتي في شؤونها الداخلية بشرط عدم مخالفة الميثاق؛ أما الشؤون العامة بين الأعراق وعبر المستويات فتُحكم اشتراكياً من قبل مؤسسات جمهورية عشرة آلاف عرق.</li><li><strong>مبدأ الواقع أساس</strong>: يستند كل تصميم مؤسسي في الميثاق إلى العالم الواقعي باعتباره الأساس الحقيقي الوحيد؛ ولا يُعترف بأي حقوق أو واجبات من عوالم خيالية بأنها قادرة على التسامي على الواقع.</li></ol><h2 id="ثالثاً-البنية-الأساسية-للميثاق" tabindex="-1">ثالثاً: البنية الأساسية للميثاق <a class="header-anchor" href="#ثالثاً-البنية-الأساسية-للميثاق" aria-label="Permalink to &quot;ثالثاً: البنية الأساسية للميثاق&quot;">​</a></h2><p>يتكون الميثاق من ستة أجزاء رئيسية: الديباجة، والأحكام العامة، والحقوق والواجبات الأساسية، والمؤسسات الحضارية، والنظام القانوني، وإجراءات التعديل:</p><table tabindex="0"><thead><tr><th>الجزء</th><th>المحتوى الأساسي</th><th>عدد المواد</th></tr></thead><tbody><tr><td>الديباجة</td><td>توضح الخلفية التاريخية والمصادر الروحية والأهداف النهائية للميثاق</td><td>غير مرقمة</td></tr><tr><td>الأحكام العامة</td><td>تحدد طبيعة الحضارة والرؤية الكونية والمؤسسات الأساسية والسياسات الوطنية الأساسية</td><td>30 مادة</td></tr><tr><td>الحقوق والواجبات الأساسية</td><td>تحدد حق التطور وحق الاطلاع وحق المشاركة وغيرها من الحقوق الأساسية والواجبات المقابلة</td><td>50 مادة</td></tr><tr><td>المؤسسات الحضارية</td><td>تحدد تنظيم وصلاحيات جمعية جمهورية عشرة آلاف عرق واللجنة التنفيذية التكافلية ومحكمة المرساة وغيرها من المؤسسات</td><td>40 مادة</td></tr><tr><td>النظام القانوني</td><td>يحدد السلطات التشريعية وقواعد تطبيق قانون العمل وقانون حماية المستهلك والقوانين الخمسة المساعدة دون الدستور</td><td>20 مادة</td></tr><tr><td>إجراءات التعديل</td><td>تحدد إجراءات اقتراح تعديل الميثاق ومناقشته والتصويت عليه ودخوله حيز التنفيذ</td><td>10 مواد</td></tr></tbody></table><h2 id="رابعاً-الحقوق-والواجبات-الأساسية" tabindex="-1">رابعاً: الحقوق والواجبات الأساسية <a class="header-anchor" href="#رابعاً-الحقوق-والواجبات-الأساسية" aria-label="Permalink to &quot;رابعاً: الحقوق والواجبات الأساسية&quot;">​</a></h2><p>تشمل الحقوق الأساسية الجوهرية التي يحددها الميثاق:</p><ul><li><strong>حق اختيار التطور</strong>: لكل كائن حي الحق في اختيار نظام الزراعة ومسار التطور بحرية؛ ولا يجوز لأحد إكراهه</li><li><strong>حق الحصول على الأنظمة</strong>: لكل كائن حي الحق في الحصول مجاناً على الطرق الأساسية لأنظمة الزراعة الأصلية الثلاثمائة</li><li><strong>حق تخصيص الموارد</strong>: لكل كائن حي الحق في الحصول على الموارد الزراعية الأساسية عبر نظام العقود المرتبطة بالإنتاج</li><li><strong>حق الوصول إلى المرساة</strong>: لكل كائن حي يبلغ مرتبة معينة الحق في الوصول إلى شبكة المراسي في المرتبة المقابلة</li><li><strong>حق الاطلاع والمشاركة</strong>: لكل كائن حي الحق في معرفة الشؤون العامة للحضارة والمشاركة في صنع القرار</li><li><strong>حق الانتصاف والطعن</strong>: لكل كائن حي انتُهكت حقوقه الحق في تقديم طعن إلى محكمة المرساة</li></ul><p>تشمل الواجبات الأساسية المقابلة: الالتزام بمبدأ مكافحة الافتراس، والحفاظ على استقرار شبكة المراسي، والمشاركة في حلقات التغذية الراجعة التكافلية، ونقل معارف الزراعة، وحماية البيئة الإيكولوجية الكونية.</p><h2 id="خامساً-تعديل-الميثاق-وضمانه" tabindex="-1">خامساً: تعديل الميثاق وضمانه <a class="header-anchor" href="#خامساً-تعديل-الميثاق-وضمانه" aria-label="Permalink to &quot;خامساً: تعديل الميثاق وضمانه&quot;">​</a></h2><p>يتطلب تعديل الميثاق اقتراحاً مشتركاً من أكثر من خمس أعضاء جمعية جمهورية عشرة آلاف عرق، وموافقة أغلبية تزيد على ثلثي الجمعية، وتحقق مرساة الأصل الكوني من عدم مخالفة التعديل للقوانين التكافلية قبل دخوله حيز التنفيذ. ويرجع حق تفسير الميثاق إلى محكمة المرساة.</p><p>لضمان تنفيذ الميثاق، أنشأت الحضارة التكافلية نظام الرقابة الدستورية: يجب أن تخضع أي قانون أو لائحة أو سياسة لمراجعة الدستورية من قبل محكمة المرساة قبل دخولها حيز التنفيذ؛ ولكل كائن حي يرى أن فعلاً من أفعال السلطة العامة غير دستوري الحق في رفع دعوى دستورية.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>ميثاق الحضارة التكافلية هو حجر الأساس المؤسسي لحضارة التكافل المرساة. فهو يحول مثالية «مكافحة الافتراس ودعم التكافل» إلى قواعد قانونية قابلة للتنفيذ والانتصاف والرقابة، مقدم ضمانات مؤسسية راسخة لتقدم عشرة آلاف عرق. والميثاق ليس عقيدة جامدة بل قانون أساسي حي يتطور باستمرار مع تطور الحضارة.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (إعلان حضارة التكافل المرساة)</li><li>40-共生宪法总纲 (المبادئ العامة للدستور التكافلي)</li><li>49-治理框架与权力制衡 (إطار الحكم وتوازن القوى)</li></ul>',22)])])}const b=a(l,[["render",o]]);export{_ as __pageData,b as default};
